-- Derived index only; signed plan/outcome and frozen snapshot JSON remain untouched.
ALTER TABLE workmanship_sim_connector_runtime_plans
 ADD COLUMN IF NOT EXISTS cache_file_batch VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.capability_id'))='simulation.model_cache.file.fetch.request' AND JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].operation_id'))='teamcenter.model_file.fetch@1' THEN NULLIF(JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].payload.batch_id')),'null') ELSE NULL END) STORED;
ALTER TABLE workmanship_sim_connector_runtime_plans
 ADD COLUMN IF NOT EXISTS cache_file_generation VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.capability_id'))='simulation.model_cache.file.fetch.request' AND JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].operation_id'))='teamcenter.model_file.fetch@1' THEN NULLIF(JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].payload.generation')),'null') ELSE NULL END) STORED;
ALTER TABLE workmanship_sim_connector_runtime_plans
 ADD COLUMN IF NOT EXISTS cache_file_snapshot_hash VARCHAR(71) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.capability_id'))='simulation.model_cache.file.fetch.request' AND JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].operation_id'))='teamcenter.model_file.fetch@1' THEN NULLIF(JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].payload.snapshot_hash')),'null') ELSE NULL END) STORED;
ALTER TABLE workmanship_sim_connector_runtime_plans
 ADD COLUMN IF NOT EXISTS cache_file_node VARCHAR(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.capability_id'))='simulation.model_cache.file.fetch.request' AND JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].operation_id'))='teamcenter.model_file.fetch@1' THEN NULLIF(JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].payload.node_key')),'null') ELSE NULL END) STORED;
ALTER TABLE workmanship_sim_connector_runtime_plans
 ADD COLUMN IF NOT EXISTS cache_file_revision VARCHAR(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.capability_id'))='simulation.model_cache.file.fetch.request' AND JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].operation_id'))='teamcenter.model_file.fetch@1' THEN NULLIF(JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].payload.item_revision_uid')),'null') ELSE NULL END) STORED;
ALTER TABLE workmanship_sim_connector_runtime_plans
 ADD COLUMN IF NOT EXISTS cache_file_dataset VARCHAR(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.capability_id'))='simulation.model_cache.file.fetch.request' AND JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].operation_id'))='teamcenter.model_file.fetch@1' THEN NULLIF(JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].payload.file_ref.dataset_uid')),'null') ELSE NULL END) STORED;
ALTER TABLE workmanship_sim_connector_runtime_plans
 ADD COLUMN IF NOT EXISTS cache_file_uid VARCHAR(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.capability_id'))='simulation.model_cache.file.fetch.request' AND JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].operation_id'))='teamcenter.model_file.fetch@1' THEN NULLIF(JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].payload.file_ref.file_uid')),'null') ELSE NULL END) STORED;
ALTER TABLE workmanship_sim_connector_runtime_plans
 ADD COLUMN IF NOT EXISTS cache_file_expected_content_hash VARCHAR(71) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.capability_id'))='simulation.model_cache.file.fetch.request' AND JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].operation_id'))='teamcenter.model_file.fetch@1' THEN NULLIF(JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].payload.expected_content_hash')),'null') ELSE NULL END) STORED;
ALTER TABLE workmanship_sim_connector_runtime_plans
 ADD COLUMN IF NOT EXISTS cache_file_content_hash VARCHAR(71) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (CASE WHEN JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.capability_id'))='simulation.model_cache.file.fetch.request' AND JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].operation_id'))='teamcenter.model_file.fetch@1' AND status='succeeded' THEN NULLIF(JSON_UNQUOTE(JSON_EXTRACT(outcome_json,'$.steps[0].result.content_hash')),'null') ELSE NULL END) STORED;
ALTER TABLE workmanship_sim_connector_runtime_plans ADD COLUMN IF NOT EXISTS cache_file_member_digest VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (MD5(JSON_ARRAY(JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].payload.node_key')),JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].payload.item_revision_uid')),JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].payload.file_ref.dataset_uid')),JSON_UNQUOTE(JSON_EXTRACT(plan_json,'$.steps[0].payload.file_ref.file_uid'))))) STORED;
CREATE INDEX IF NOT EXISTS ix_cache_file_completed_member ON workmanship_sim_connector_runtime_plans(tenant_gid,actor_gid,cache_file_batch,cache_file_generation,cache_file_snapshot_hash,cache_file_member_digest,status,cache_file_content_hash,plan_id);
CREATE INDEX IF NOT EXISTS ix_cache_file_completed_page ON workmanship_sim_connector_runtime_plans(tenant_gid,actor_gid,cache_file_batch,cache_file_generation,cache_file_snapshot_hash,status,plan_id);
